            entity.Property(e => e.PorquitaCalculado).HasComputedColumnSql("(case when CONVERT([numeric](2),rtrim(ltrim([porquita])))=(0) AND [mracont_a]=[mra_aplc_a_inicial] AND NOT [MARCA_CAC] like '%G%' AND NOT (isnull([ESTATUS],'')='AS' OR isnull([ESTATUS],'')='CF' OR isnull([ESTATUS],'')='CA' OR isnull([ESTATUS],'')='BJ' OR isnull([ESTATUS],'')='AM' OR isnull([ESTATUS],'')='AT' OR isnull([ESTATUS],'')='AJ' OR isnull([ESTATUS],'')='AF' OR isnull([ESTATUS],'')='AB') AND NOT ([GEST]='5358' OR [GEST]='5224' OR [GEST]='4440' OR [GEST]='4180') AND CONVERT([date],[FECH_APER],(103))<CONVERT([date],left(CONVERT([varchar](10),dateadd(month,(-6),CONVERT([date],getdate(),(103)))),(8))+'01') then case when CONVERT([int],[mra_aplc_a])=(1) AND NOT isnull([MARCA_CAC],'') like '%B%' AND (isnull([PRODUCTO],'')='Congelada' OR isnull([estatus],'')='BR') then (27) when CONVERT([int],[mra_aplc_a])=(2) AND NOT isnull([MARCA_CAC],'') like '%B%' AND (isnull([PRODUCTO],'')='Congelada' OR isnull([estatus],'')='BR') then (33) when CONVERT([int],[mra_aplc_a])=(1) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([PRODUCTO],'')<>'Congelada' AND isnull([estatus],'')<>'BR' then (15) when CONVERT([int],[mra_aplc_a])=(2) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([PRODUCTO],'')<>'Congelada' AND isnull([estatus],'')<>'BR' then (20) when [MARCA_CAC]='E3' OR [MARCA_CAC]='F6' OR [MARCA_CAC]='F5' OR [MARCA_CAC]='F4' OR [MARCA_CAC]='F3' OR [MARCA_CAC]='F1' OR [MARCA_CAC]='A8' OR [MARCA_CAC]='A2' then case when CONVERT([int],[mra_aplc_a])=(3) then (64) when CONVERT([int],[mra_aplc_a])=(4) then (69) when CONVERT([int],[mra_aplc_a])=(5) then (74) when CONVERT([int],[mra_aplc_a])=(6) then (78) when CONVERT([int],[mra_aplc_a])=(7) then (84) when CONVERT([int],[mra_aplc_a])>=(8) then (90)  end when ([MARCA_CAC]='D6' OR [MARCA_CAC]='D5' OR [MARCA_CAC]='D4' OR [MARCA_CAC]='D3' OR [MARCA_CAC]='C6' OR [MARCA_CAC]='C5' OR [MARCA_CAC]='C4' OR [MARCA_CAC]='C3' OR [MARCA_CAC]='B2' OR [MARCA_CAC]='B1' OR [MARCA_CAC]='A6' OR [MARCA_CAC]='A5' OR [MARCA_CAC]='A4' OR [MARCA_CAC]='A3' OR [MARCA_CAC]='A1') AND isnull([estatus],'')<>'BR' then case when CONVERT([int],[mra_aplc_a])=(3) then (60) when CONVERT([int],[mra_aplc_a])=(4) then (64) when CONVERT([int],[mra_aplc_a])=(5) then (68) when CONVERT([int],[mra_aplc_a])=(6) then (74) when CONVERT([int],[mra_aplc_a])=(7) then (78) when CONVERT([int],[mra_aplc_a])>=(8) then (89)  end when NOT ([MARCA_CAC]='P3' OR [MARCA_CAC]='P1' OR [MARCA_CAC]='F6' OR [MARCA_CAC]='F5' OR [MARCA_CAC]='F4' OR [MARCA_CAC]='F3' OR [MARCA_CAC]='F1' OR [MARCA_CAC]='E3' OR [MARCA_CAC]='A8' OR [MARCA_CAC]='A2') AND isnull([estatus],'')='BR' then case when CONVERT([int],[mra_aplc_a])=(3) then (64) when CONVERT([int],[mra_aplc_a])=(4) then (69) when CONVERT([int],[mra_aplc_a])=(5) then (74) when CONVERT([int],[mra_aplc_a])=(6) then (78) when CONVERT([int],[mra_aplc_a])=(7) then (84) when CONVERT([int],[mra_aplc_a])>=(8) then (90)  end  end else case when CONVERT([numeric](2),rtrim(ltrim([porquita])))=(0) AND [mracont_a]=[mra_aplc_a_inicial] AND NOT [MARCA_CAC] like '%G%' AND ([GEST]='5358' OR [GEST]='5224' OR [GEST]='4440' OR [GEST]='4180') AND CONVERT([date],[FECH_APER],(103))<CONVERT([date],left(CONVERT([varchar](10),dateadd(month,(-6),CONVERT([date],getdate(),(103)))),(8))+'01') then case when CONVERT([int],[mra_aplc_a])=(1) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([estatus],'')='BR' then (28) when CONVERT([int],[mra_aplc_a])=(2) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([estatus],'')='BR' then (34) when CONVERT([int],[mra_aplc_a])=(1) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([estatus],'')<>'BR' then (16) when CONVERT([int],[mra_aplc_a])=(2) AND NOT isnull([MARCA_CAC],'') like '%B%' AND isnull([estatus],'')<>'BR' then (28) when [MARCA_CAC]='E3' OR [MARCA_CAC]='F6' OR [MARCA_CAC]='F5' OR [MARCA_CAC]='F4' OR [MARCA_CAC]='F3' OR [MARCA_CAC]='F1' OR [MARCA_CAC]='A8' OR [MARCA_CAC]='A2' then case when CONVERT([int],[mra_aplc_a])=(3) then (61) when CONVERT([int],[mra_aplc_a])=(4) then (67) when CONVERT([int],[mra_aplc_a])=(5) then (73) when CONVERT([int],[mra_aplc_a])=(6) then (90) when CONVERT([int],[mra_aplc_a])=(7) then (90) when CONVERT([int],[mra_aplc_a])>=(8) then (90)  end when ([MARCA_CAC]='D6' OR [MARCA_CAC]='D5' OR [MARCA_CAC]='D4' OR [MARCA_CAC]='D3' OR [MARCA_CAC]='C6' OR [MARCA_CAC]='C5' OR [MARCA_CAC]='C4' OR [MARCA_CAC]='C3' OR [MARCA_CAC]='B2' OR [MARCA_CAC]='B1' OR [MARCA_CAC]='A6' OR [MARCA_CAC]='A5' OR [MARCA_CAC]='A4' OR [MARCA_CAC]='A3' OR [MARCA_CAC]='A1') AND isnull([estatus],'')<>'BR' then case when CONVERT([int],[mra_aplc_a])=(3) then (53) when CONVERT([int],[mra_aplc_a])=(4) then (64) when CONVERT([int],[mra_aplc_a])=(5) then (71) when CONVERT([int],[mra_aplc_a])=(6) then (88) when CONVERT([int],[mra_aplc_a])=(7) then (88) when CONVERT([int],[mra_aplc_a])>=(8) then (88)  end when NOT ([MARCA_CAC]='P3' OR [MARCA_CAC]='P1' OR [MARCA_CAC]='F6' OR [MARCA_CAC]='F5' OR [MARCA_CAC]='F4' OR [MARCA_CAC]='F3' OR [MARCA_CAC]='F1' OR [MARCA_CAC]='E3' OR [MARCA_CAC]='A8' OR [MARCA_CAC]='A2') AND isnull([estatus],'')='BR' then case when CONVERT([int],[mra_aplc_a])=(3) then (61) when CONVERT([int],[mra_aplc_a])=(4) then (67) when CONVERT([int],[mra_aplc_a])=(5) then (73) when CONVERT([int],[mra_aplc_a])=(6) then (90) when CONVERT([int],[mra_aplc_a])=(7) then (90) when CONVERT([int],[mra_aplc_a])>=(8) then (90)  end  end  end end)", false);
